    Text = "오라! 광기, 살육, 고통을 음표 삼아, 별들 사이에서 빛나는 진혼곡을 연주하자. \n그 우둔한 혼돈의 절대적 존재는, 지금도 미래에도 깨어나서는 안 된다."
