    Text = "표시된 가격은 참고용입니다. 결제 시에는 현재의 실타래제 환율이 적용된 가격으로 적용됩니다."
  },
  PanelText_UI_Events_Panel_Arachne_StageGroup_Text_C_Introduction_Content = {
    Text = "조명이 켜진다. 박수가 잦아든다. 관객들이 기대하고 있다.\n무대에 오를 시간이다, 나의 사랑하는 아이들아. 올라가라, 공연하라, 너희의 폐부를 찢어 보여라, 너희의 가장 깊은 비밀을 팔아라. 너희의 가장 처참한 상처로, 사람들을 즐겁게 할 디저트를 만들어라. 무대 위에서 오직 너만을 위해 밝혀진 그 빛을 탐욕스럽게 즐겨라, 장막이 너와 관객을 함께 묻어버릴 때까지.\n이것은 너희에게 운명 지어진 무대다, 올라서라! 두려워하지 마라, 무대 공포는 필요 없다."
  },
