  PanelText_UI_Events_Panel_Caraboo_StageGroup_Text_C_Introduction_Content = {
    Text = "♪~~🎵~~♪~~🎵~~♪~~🎵~~\n설산 아래에서, 모든 안내자는 그것을 기억하고, 모든 아이들은 여전히 그것을 노래한다. 그녀는 우뚝 선 설산의 의지가 육체가 된 것이며, 자비로운 여신 우모파티이다. 그녀의 신력은 인간계에 흩어져 있고, 그녀의 보물은 찾을 수 없다. 그것들은 손에 닿을 듯 가깝고, 흔적도 없이 사라진다. 무엇인가를 포기하라. 무엇인가를 붙잡아라. 여신의 참된 모습에 불성실타래한 자는 죽은 설산과 함께, 영원히 설산에 묻힐 것이다."
  },
