  PanelText_UI_Events_Panel_Castor_StageGroup_Text_C_Introduction_Content = {
    Text = "한 새의 삶은 처음부터 자유로울 운명이었다. 그것이 알을 깨고, 죽음의 손아귀에서 생명의 자유를 되찾는 순간을, 너는 반드시 보아야 한다. 그리고 둥지의 안락함을 떠나 홀로 하늘을 배우며 살아갈 자유를 움켜쥐는 순간 역시, 너는 반드시 보아야 한다. 만약 그 자유의 열쇠가 죽음의 심연 속으로 떨어진다면, 새는 주저 없이 뛰어내려 좁디좁은 생명과 무한한 자유 사이에서, 죽음의 폭풍을 정면으로 맞이할 것이다."
  },
