  PanelText_UI_Events_Panel_Clementine_StageGroup_Text_C_Introduction_Content = {
    Text = "그때부터, 그녀는 단 한 방울의 눈물도 흘리지 않았다.\n홀로 떠돌며, 온갖 이형으로 가득한 세상을 배회한다.\n거대한 계획이 시작되려 한다. 그녀의 마지막 막을 장식하는 작별 인사로서.\n그녀는 최고의 심리학자였고, 이것이 그녀의 가장 완벽한 치료였다."
