  PanelText_UI_Events_Panel_ClotherLottery_Text_Free_Content = {Text = "무료"},
  PanelText_UI_Events_Panel_Daffodil_StageGroup_Text_C_Introduction_Content = {
    Text = "이 작은 해변 마을에는 번화한 상점가가 있습니다. 해상 무역 덕분에 온갖 최신 상품들이 모여있으며, 충분한 레오판만 있다면 얼마든지 만족스러운 상품을 얻을 수 있습니다.\n 거리 모퉁이에 있는 작은 가게 하나를 제외하고 말이죠. 그곳은 신비한 골동품으로 가득하고, 파이프 연기 속에서 넓은 챙 모자를 쓴 주인이 나타나 천천히 미소 짓고 있을 것입니다.\n “고민 해결 상점에 오신 것을 환영합니다. 이곳에서는 당신의 모든 필요를 충족시켜 드립니다. 충분한 보수만 지불한다면...”\n “물론, 물론. 가격은 합리적이며, 그 누구도 속이지 않습니다.”"
  },
