  PanelText_UI_Events_Panel_KathiguRa_StageGroup_Text_C_Introduction_Content = {
    Text = "그녀가 다시 대지 위에 서자, 모든 것을 재로 만들어버릴 복수가 약속대로 찾아왔다.\n 그것은 멈추지 않는 추격, 폭염의 주인인 살아 있는 불꽃이었다. 그녀는 모든 길을 걸으며, 죽음과 계약한 자들을 사냥할 것이다.\n 도망쳐라, 도망쳐라, 가장 깊은 어둠 속으로, 자신이 결코 찾아내지 못할 것이라 믿는 곳으로 도망쳐라.\n 하지만 소용없다. 그녀는 모든 세계를 짓밟을 것이며, 모든 이를 사냥하여, 결국 모든 것을 재로 만들 때까지 끝없이 추적할 것이다."
  },
