  PanelText_UI_Events_Panel_Lily_StageGroup_Text_C_Introduction_Content = {
    Text = "돌이 맡기는 미션는 언제나 쉽지 않다. \n언제나 모두에게 \"재밌게 놀아\" 라고 당부했지만, 처음으로 깨어남체들을 데리고 나가는 수호자가 떨지 않을 수 있을까?\n그래도, \"재밌게 놀아\"야 한다는 건 꼭 기억하자."
