  PanelText_UI_Events_Panel_Mosk_StageGroup_Text_C_Introduction_Content = {
    Text = "하늘~ 쨍쨍~ 바다~ 고요~\n모스~ 친구~ 알탄이~ 출항!\n폭풍, 두렵지 않아, 번개, 안 두려워, 모스, 친구, 우리 알탄이~\n자유를 위해, 출·발·대·행·진!"
