  },
  PanelText_UI_Events_Panel_Mouchette_StageGroup_Text_C_Introduction_Content = {
    Text = "갑자기 어느 날, 당신은 자신이 달라졌다는 것을 깨달았습니다. \n 아무도 이를 알아차리지 못했어요, 왜냐하면 당신은 똑같은 행동과 똑같은 아름다운 외모를 가지고 있었으니까요. \n 하지만 당신은 잘 알고 있습니다, 원래 선홍빛의 심장이 이미 안개로 이루어진 가면으로 덮여 있다는 것을. \n “내가 계속 위장할 수 있다면, 그럼에도 불구하고 나는 이전의 나일까요?” \n 기쁘게도, 이 질문은 당신의 뇌에서 1초 이상 머물지 않았습니다. 어쨌든 그 가면을 벗기기 전까지는 아무도 당신의 진짜 생각을 알 수 없으니까요. \n “그럼, 먼저 출발합시다~”"
  },
