  PanelText_UI_Events_Panel_OriDoll_StageGroup_Text_C_Introduction_Content = {
    Text = "그녀는 세계의 끝에 서 있는 거대한 문을 바라보며, 한 치의 주저함 없이 발을 내디뎠다.\n찰칵—손잡이를 비틀고, 문 너머를 간절히 들여다본다.\n그러나 그 너머에는 공허만이 존재했다. 그녀는 허공을 디디고, 끝없는 허무 속으로 떨어졌다.\n쉽게 주어지는 선물에는 언제나 치명적인 대가가 따른다는 사실타래을, 그녀는 이미 알았어야 했다."
