    Text = "신이 약속한 때가 다가오고 있다.\n수 천 년의 기다림이 환희의 끝을 맞이하고, 약속의 땅이 바다로부터 솟아오를 것이다.\n신은 신모의 가슴으로부터 태어나고, 일곱째 날이 끝날 때 새로운 세계가 강림할 것이다."
