  PanelText_UI_Events_Panel_Pickman_StageGroup_Text_C_Introduction_Content = {
    Text = "이성와 크래시 사이, 기교활한 그림이 서서히 펼쳐진다.\n네가 경멸하는 환각은 화려한 색채를 그려내고,\n네가 두려워하는 통제 상실타래은 충성의 형태를 구성한다.\n여기서, 광란은 예술의 본능이며, 세계의 근원이고,\n유일하게 거짓말하지 않는 진실타래이다."
