  PanelText_UI_Events_Panel_Pollux_StageGroup_Text_C_Introduction_Content = {
    Text = "그러한 증오와 사랑, 온정과 피해, 한때 소유했던 것과 놓쳤던 것이 이미 얽혀서 풀 수 없게 되었다.\n 그럼 우리의 같은 골혈이 흐르게 하자. 그것들은 한곳에 모여 우리의 불가분의 운명을 이룰 것이다."
