  PanelText_UI_Events_Panel_Saya_StageGroup_Text_C_Introduction_Content = {
    Text = "과학, 중요하지 않다.\n윤리, 중요하지 않다.\n도덕, 중요하지 않다.\n생명, 죽음, 희망, 절망…… 마지막의 마지막, 지하실타래의 노트 위에 두 가지 필체로 같은 추론이 남겨졌다.\n그들은 「보거라, 사랑이야말로 영원하고 유일한 명제다.」라 말했다 전해진다."
