  PanelText_UI_Events_Panel_Sorel_StageGroup_Text_C_Introduction_Content = {
    Text = "수년 후, 한 전기 작가가 황혼녘 그녀의 집 문을 두드렸다.\n그날 그들은 많은 이야기를 나누었다. 마노 원석에서부터 장미가 시들어간 저택에 이르기까지……\n이제, 작가는 그 흩어진 말들을 한 권의 책으로 엮어 여기 모인 여러분께 바친다."
