  PanelText_UI_Events_Panel_StElmosFire_StageGroup_Text_C_Introduction_Content = {
    Text = "오래된 육분의로 별들의 각을 재고, 고대의 해도는 예정된 항로를 그리며, 낡은 나침반은 나아갈 방향을 정한다.\n 깊고 차가운 어둠 속에서도, 평범한 구리와 쇠로 앞길을 밝히는 탐험가들이 있다.\n모든 길잡이들이, 결코 길을 잃지 않기를."
