  PanelText_UI_Events_Panel_Xu_StageGroup_Text_C_Introduction_Content = {
    Text = "사랑에서 원망이 생기고, 원망에서 증오가 생긴다. 끈적이고, 연속적이며, 음침한……\n하늘에 기도를 해도 응답이 없고, 땅에 도망칠 길도 없다. 그래서 밤안개 속에 숨어 있는 웃음소리가 당신의 호출에 응답했다. 당신은 어떤 대가도 치르지 않아도 된다. \n그녀를 바라보고, 그녀를 따르며, 그녀와 하나가 되어, 그녀가 된다."
